$ cat hola.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    double notas[100];
    int cantidad = 0;
    char t[30];
    while (cantidad < 100) {
        printf("Nota (o 'fin'): ");
        scanf("%s", t);
        if (strcmp(t, "fin") == 0) {
            break;
        }
        notas[cantidad] = atof(t);
        cantidad++;
    }
    if (cantidad > 0) {
        double suma = 0;
        for (int i = 0; i < cantidad; i++) {
            suma += notas[i];
        }
        printf("Promedio: %.1f\n", suma / cantidad);
    } else {
        printf("No cargaste notas\n");
    }
    return 0;
}
